using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
public static class BoundsRead {public static object Read(){var s=SceneManager.GetActiveScene();var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Stealth_Level"));var t=root.transform.Find("Retained_Pod_and_Habitat");var r=t.GetComponentsInChildren<Renderer>().Where(x=>x.enabled).ToArray();var b=r[0].bounds;foreach(var a in r)b.Encapsulate(a.bounds);var names=new[]{"SD_PPEStation","SD_MaintenanceStation","P02_WallStorageCabinet_B5_Lite","LP_SampleColdCabinet"};return new{podBounds=new{min=b.min.ToString(),max=b.max.ToString()},props=names.Select(n=>{var g=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Afrer_Seconds/05.Model/Props/Common/"+n+".prefab");var rr=g.GetComponentsInChildren<Renderer>();var bb=rr[0].bounds;foreach(var x in rr)bb.Encapsulate(x.bounds);return new{name=n,size=bb.size.ToString(),min=bb.min.ToString(),max=bb.max.ToString(),colliders=g.GetComponentsInChildren<Collider>().Length};}).ToArray()};}}
